source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python -c "
import json, glob
# Search all JSON files for n_total=100 or total=100
for f in glob.glob('/root/autodl-tmp/recovery_aware_struct_prune/results/*.json'):
    try:
        d = json.load(open(f))
        nt = d.get('n_total') or d.get('total')
        if nt == 100:
            print(f'N=100: {f} accuracy={d.get(\"accuracy\")}')
    except:
        pass
# Also check for math500 grpo standard 25 files with accuracy ~0.128
for f in glob.glob('/root/autodl-tmp/recovery_aware_struct_prune/results/*standard*25*.json'):
    try:
        d = json.load(open(f))
        acc = d.get('accuracy')
        nt = d.get('n_total') or d.get('total')
        print(f'standard_25: {f.split(\"/\")[-1]} accuracy={acc}, n_total={nt}')
    except:
        pass
"
